begin;
create table if not exists public.organization_mfa_policies(id uuid primary key default gen_random_uuid(),organization_id uuid not null unique references public.organizations(id) on delete cascade,enforcement text not null default 'optional' check(enforcement in('optional','admins','all')),grace_period_hours integer not null default 24 check(grace_period_hours between 0 and 168),recovery_codes_required boolean not null default true,updated_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.user_mfa_status(user_id uuid primary key references auth.users(id) on delete cascade,aal text not null default 'aal1',verified_factor_count integer not null default 0,last_verified_at timestamptz,recovery_codes_generated_at timestamptz,updated_at timestamptz not null default now());
alter table public.organization_mfa_policies enable row level security; alter table public.user_mfa_status enable row level security;
create policy "members read mfa policy" on public.organization_mfa_policies for select using(exists(select 1 from public.organization_members m where m.organization_id=organization_mfa_policies.organization_id and m.user_id=auth.uid() and coalesce(m.status,'active')='active'));
create policy "admins manage mfa policy" on public.organization_mfa_policies for all using(exists(select 1 from public.organization_members m where m.organization_id=organization_mfa_policies.organization_id and m.user_id=auth.uid() and m.role in('owner','admin') and coalesce(m.status,'active')='active')) with check(exists(select 1 from public.organization_members m where m.organization_id=organization_mfa_policies.organization_id and m.user_id=auth.uid() and m.role in('owner','admin') and coalesce(m.status,'active')='active'));
create policy "users read own mfa status" on public.user_mfa_status for select using(user_id=auth.uid());
commit;